-- Complete reference curricula for s01-m01, s02-m01 and s03-m01.
-- Existing immutable versions remain available for audit and rollback.
SET lock_timeout = '5s';

CREATE TEMP TABLE reference_lesson_specs (
 module_id text, lesson_id text, title text, duration text, objective text,
 hook text, insight text, example_text text, practice text, quiz_question text,
 correct_answer text, wrong_answer_1 text, wrong_answer_2 text, interaction text
) ON COMMIT DROP;

INSERT INTO reference_lesson_specs VALUES
('s01-m01','l01-01','Основи на AI за бизнес — какво работи и какво не','25 мин','да различаваш задача за AI от решение, което изисква човешка преценка','Екипът ти губи часове в AI, но резултатът пак се пренаписва от нулата.','AI е силен при ясно зададен контекст, критерий и проверима чернова; отговорността за факти и решение остава човешка.','Вместо „направи стратегия“, собственикът дава цел, аудитория, ограничения и иска три варианта с рискове.','Избери една повтаряема бизнес задача и опиши входа, желания изход и човешката проверка.','Коя задача е най-подходяща за първи AI експеримент?','Повтаряема задача с ясен вход и проверим резултат','Окончателно юридическо решение без проверка','Неясна задача без критерий за успех','decision_tree'),
('s01-m01','l01-02','Prompt engineering на професионално ниво','30 мин','да създаваш prompt с контекст, задача, ограничения и критерий за качество','Получаваш общ текст, защото AI трябва да отгатва кой си, за кого пишеш и как изглежда добрият резултат.','Професионалният prompt не е магическа фраза, а кратък бриф: роля, контекст, конкретна задача, формат и тест за качество.','За имейл оферта се задават клиент, проблем, доказателство, тон, дължина и забранени клишета.','Създай prompt за реална задача и добави критерий, по който ще отхвърлиш слаб отговор.','Кой елемент най-много намалява двусмислието?','Конкретен контекст и измерим критерий','Повече удивителни знаци','Изречението „бъди креативен“ без пример','prompt_builder'),
('s01-m01','l01-03','Мулти-моделна стратегия: ChatGPT, Claude, Gemini','35 мин','да избираш AI модел според задача, риск и нужда от проверка','Един и същ модел се използва за всичко, а екипът бърка навик с правилен избор.','Сравнявай моделите по качество на конкретната задача, работа с източници, контекст, цена и поверителност — не по обща класация.','Един модел прави първа структура, втори атакува слабите места, а човекът проверява фактите и финалното решение.','Пусни една и съща бизнес задача в два модела и оцени резултатите по пет еднакви критерия.','Как се прави честно сравнение между два модела?','С един и същ вход и предварително зададена рубрика','С различни задачи и по усещане','Само по скоростта на първия отговор','matching'),
('s01-m01','l01-04','AI за бизнес решения всеки ден','30 мин','да вградиш AI в решение, без да делегираш отговорността','AI предлага убедително действие, но пропуска важен разход и екипът го приема без проверка.','Надеждният цикъл е: формулирай решение, събери данни, поискай алтернативи, тествай допусканията и запиши защо човекът избира финала.','При избор на кампания AI генерира сценарии, но собственикът сверява бюджет, капацитет и реални данни за конверсия.','Използвай цикъла върху едно предстоящо решение и запиши две допускания, които трябва да провериш.','Кой носи отговорността за бизнес решение, подпомогнато от AI?','Човекът, който проверява данните и взема решението','AI моделът, защото е дал препоръката','Платформата, в която е написан prompt-ът','client_simulation'),

('s02-m01','pv01-01','Направи одит на последните си 5 видеа и намери къде хората спират да гледат','5 мин','да откриваш конкретната секунда и причината за отпадане','Гледанията са ниски, но без одит всяка следваща промяна е просто предположение.','Сравни първите 3 секунди, първия спад и момента на обещаната стойност във всяко от петте видеа.','Видео започва с 4 секунди поздрав; графиката пада преди зрителят да разбере ползата.','Запиши в таблица hook, първи спад и една корекция за всяко от последните пет видеа.','Какво прави одита приложим?','Свързва конкретен спад с конкретна промяна','Брои само общите гледания','Копира най-популярното чуждо видео','sequence_sort'),
('s02-m01','pv01-02','Попълни теста за ниво и получи своя старт-точка','5 мин','да определяш следващото умение според доказателства, а не самочувствие','Ако тренираш напреднал монтаж, докато звукът е неразбираем, усилието не подобрява резултата.','Стартовото ниво се определя по наблюдаемо изпълнение: послание, картина, звук, монтаж и публикуване.','Автор с добра камера, но без ясна тема започва от стратегия, не от нов обектив.','Оцени последно видео по петте области и избери една слабост за тази седмица.','Коя стартова точка е най-полезна?','Най-слабото умение, което блокира зрителя','Най-скъпият инструмент','Темата, която изглежда най-впечатляващо','checklist'),
('s02-m01','pv01-03','Провери настройките „Your Algorithm“ в Instagram и виж защо ти показва това съдържание','5 мин','да разпознаваш сигналите, с които обучаваш собствения си feed','Изследваш нишата през feed, който е оптимизиран по старите ти навици, а не по целевата аудитория.','Следвания, запазвания, време на гледане и „не ме интересува“ оформят извадката, от която учиш.','Седмица целево взаимодействие с качествени примери променя препоръките и прави проучването по-полезно.','Прегледай настройките, премахни три нерелевантни сигнала и запази пет силни примера от нишата.','Кой сигнал най-ясно показва интерес?','Последователно гледане и запазване на релевантно съдържание','Случайно отваряне на един профил','Цветът на иконата на приложението','reflection'),
('s02-m01','pv01-04','Начертай FRAME картата за собствения си проект','5 мин','да превръщаш видео идея в измерим FRAME процес','Снимането започва веднага, но няма връзка между цел, запис, монтаж и резултат.','FRAME свързва Focus, Record, Assemble, Measure и Evolve в един цикъл с ясна проверка на всяка стъпка.','За продуктово видео Focus е записване за демо, Measure е процентът зрители, стигнали CTA.','Начертай петте етапа за реален проект и запиши по един измерим резултат за всеки.','Кой етап затваря цикъла и определя следващата промяна?','Evolve','Record','Assemble','step_reveal'),
('s02-m01','pv01-05','Инсталирай и тествай 3 безплатни AI инструмента за видео','5 мин','да оценяваш AI инструмент по реална задача и риск','Списъкът с инструменти расте, но никой не знае кой спестява време и кой добавя грешки.','Тествай еднакъв вход, измери време и качество и провери лиценз, поверителност и възможност за корекция.','Три инструмента генерират субтитри; печели не най-бързият, а този с най-малко поправки на български.','Тествай три инструмента върху един 30-секунден клип и попълни сравнителна рубрика.','Кой тест е честен?','Един и същ клип и еднакви критерии','Различен клип за всеки инструмент','Само рекламните обещания на сайтовете','before_after'),
('s02-m01','pv01-06','Заснеми 10-секунден клип само с наличното оборудване','5 мин','да постигаш ясна идея преди да купуваш техника','Отлагаш публикуването, защото нямаш идеалната камера, а основният проблем е неясният кадър.','Светлина, стабилност, чист звук и едно действие са достатъчни за полезен 10-секунден тест.','Телефон до прозорец, фиксиран върху книги, показва продукт с едно ясно движение.','Заснеми и прегледай три дубъла; промени само по един фактор между дублите.','Какво трябва да променяш между тестовите дубъли?','Само един фактор, за да видиш ефекта','Всички настройки наведнъж','Оборудването преди идеята','checklist'),
('s02-m01','pv01-07','Определи 3-те content pillar-а на своята ниша','5 мин','да избираш три устойчиви теми, свързани с нужда на аудиторията','Публикуваш случайни идеи и зрителят не може да обясни защо да се върне.','Силен pillar пресича експертиза, често клиентско напрежение и формат, който можеш да поддържаш.','Фитнес треньор избира техника, хранене в реалния живот и проследяване на прогреса.','Напиши 10 клиентски въпроса, групирай ги и назови трите повтарящи се теми.','Кой pillar е устойчив?','Тема с реално търсене и твоя доказуема експертиза','Еднократен тренд без връзка с офертата','Всичко, което конкурентите публикуват','matching'),
('s02-m01','pv01-08','Направи чеклист и план за следващите 30 дни','5 мин','да превръщаш целта за публикуване в изпълним ритъм','Календарът е пълен с идеи, но няма дни за подготовка, снимане и анализ.','Работещият план резервира капацитет за целия цикъл, а не само дата за публикация.','В понеделник се пишат hooks, сряда е batch снимане, петък — анализ и следваща хипотеза.','Планирай четири седмици с конкретен собственик, срок и критерий за готовност.','Кое прави 30-дневния план изпълним?','Отделно време за подготовка, производство и анализ','Само списък с 30 заглавия','Публикуване без буфер и проверка','prompt_builder'),
('s02-m01','pv01-09','Гледай 10 видеа в нишата си и маркирай точната секунда, в която те закачат или губят','5 мин','да анализираш вниманието по секунди','„Харесва ми“ не показва кой момент е задържал вниманието и кой го е загубил.','Маркирай визуална промяна, нова информация, пауза и обещание точно преди решението да останеш или да скролнеш.','В 0:02 се появява резултатът; в 0:07 дълго обяснение без нов кадър причинява отпадане.','Направи timeline бележки за 10 видеа и изведи три повтарящи се модела.','Коя бележка е полезна за повторение?','Точна секунда, стимул и реакция','„Видеото е добро“','Само броят харесвания','flip_cards'),
('s02-m01','pv01-10','Пресъздай хук, който те е спрял да скролваш, върху собствена тема','5 мин','да пренасяш структура на hook без копиране','Копираното изречение звучи чуждо, но структурата зад него може да се адаптира етично.','Раздели hook-а на напрежение, конкретика и обещана полза; после смени доказателството с твое.','„Три грешки при осветление“ става „Три места, където лендингът губи клиента“ със собствен пример.','Напиши три версии на структурата за твоя тема и заснеми най-конкретната.','Как адаптираш чужд hook правилно?','Запазваш механизма, но използваш собствено твърдение и доказателство','Копираш текста дума по дума','Сменяш само една дума','scenario'),
('s02-m01','pv01-11','Засечи с таймер колко секунди издържаш на бавно видео срещу бързо','5 мин','да избираш темпо според когнитивното натоварване','Бързото рязане прикрива липса на идея, а прекалено бавното начало губи ясното обещание.','Темпото е функция на новата информация: кадърът се сменя, когато вниманието има причина, не по фиксирана рецепта.','Демонстрация може да задържи дълъг кадър, ако всяка секунда показва видима промяна.','Сравни два клипа, запиши секундата на скука и причината, после направи една редакция.','Кога дългият кадър работи?','Когато носи развиваща се информация или емоция','Когато няма какво да се покаже','Винаги след точно десет секунди','reflection'),
('s02-m01','pv01-12','Направи списък с 5 визуални модела, които разпознаваш инстинктивно в чужди видеа','5 мин','да назоваваш визуални модели и тяхната функция','Виждаш силна визия, но не можеш да обясниш как да я повториш целенасочено.','Моделът се описва като композиция, движение, преход и ефект върху вниманието.','Ръка влиза в foreground, разкрива продукта и създава естествен wipe към следващ кадър.','Събери пет screenshot-а и под всеки запиши структурата и подходяща собствена употреба.','Кое описание е приложимо?','Описва видимата структура и ефекта ѝ','Казва само „изглежда яко“','Назовава приложението за монтаж','flip_cards'),
('s02-m01','pv01-13','Сравни 2 версии на едно видео — информативна и емоционална — и избери по-силната','5 мин','да избираш версия според целта на видеото','Емоционалната версия печели гледане, но може да не обясни следващата стъпка; информативната може да е ясна, но без напрежение.','Изборът зависи от целта и наблюдаваното действие, не от личния вкус на автора.','За awareness се тества задържане; за оферта — качествени кликове и запитвания.','Покажи двете версии на пет души и сравни разбиране, емоция и намерение за действие.','По какво избираш победител?','По метриката, свързана с целта','По любимия цвят на автора','По броя използвани преходи','decision_tree'),
('s02-m01','pv01-14','Заснеми 15 секунди, в които градиш доверие само с поглед и говор','5 мин','да използваш присъствие пред камера вместо ефекти','Звучиш като прочетен текст и зрителят усеща дистанция още преди аргументите.','Доверието идва от стабилен поглед към обектива, естествени паузи, конкретно твърдение и спокоен край.','Говорителят казва един проверим резултат, оставя пауза и не прикрива несигурността с бърза реч.','Запиши три дубъла: разговорен, прекалено бърз и с осъзнати паузи; избери по критерии.','Кой детайл най-често увеличава усещането за увереност?','Ясна мисъл с естествена пауза','Непрекъснато бързо говорене','Поглед към екрана вместо обектива','client_simulation'),
('s02-m01','pv01-15','Провери собствено видео за признаци на умора на зрителя','5 мин','да откриваш повторение, празен кадър и спад в темпото','Видеото е кратко, но повтаря една теза три пъти и се усеща по-дълго от реалното.','Умората идва, когато няма нова информация, визуална промяна или нарастващо значение.','Две сходни изречения се сливат в едно, а B-roll показва доказателството вместо украса.','Маркирай всеки момент без нова стойност и съкрати поне 15% без загуба на смисъл.','Кой е сигнал за умора?','Повторение без нова информация или промяна','Една ясна пауза след важна теза','Кратък кадър с доказателство','checklist'),
('s02-m01','pv01-16','Напиши 15 идеи по 5 различни формата','5 мин','да превръщаш една тема в разнообразни видео формати','След три публикации „нямаш идеи“, защото търсиш нова тема вместо нов ъгъл.','Evergreen, UGC, POV, FAQ и мит дават пет различни зрителски входа към една експертиза.','Темата „домашно кафе“ става урок, клиентска реакция, бариста POV, отговор и развенчан мит.','Избери три теми и създай по една идея във всеки от петте формата.','Как се създават 15 свързани идеи?','Три теми по пет различни формата','Петнайсет случайни тренда','Един и същ клип с нова музика','matching'),
('s02-m01','pv01-17','Създай рубрика с име и повтаряща се структура','5 мин','да проектираш разпознаваема поредица, която може да се произвежда','Всяко видео започва от нулата и аудиторията няма сигнал какво да очаква следващия път.','Рубриката има обещание, повтарящ се ритъм и място за нов пример — последователна форма, не повтарящ се текст.','„Одит за 60 секунди“ винаги показва проблем, доказателство и една корекция върху различен сайт.','Назови рубриката, опиши трите ѝ части и планирай първите четири епизода.','Кое прави рубриката разпознаваема?','Постоянно обещание и структура с нови случаи','Еднакъв сценарий без нова стойност','Само една и съща начална музика','prompt_builder'),
('s02-m01','pv01-18','Заснеми 20 секунди зад кадър от текущ проект','5 мин','да превръщаш процеса в доказателство за компетентност','Показваш само полирания финал и пропускаш решенията, които изграждат доверие.','Смисленият behind-the-scenes показва избор, трудност и защо е взето решение, а не хаотични клипове от офиса.','Кадърът показва как се мести светлина, сравнява резултата и обяснява причината с едно изречение.','Заснеми проблем, действие и резултат в три последователни кадъра.','Коя BTS структура носи стойност?','Проблем → решение → видим резултат','Случайни кадри без контекст','Само логото на проекта','sequence_sort'),
('s02-m01','pv01-19','Събери 3 клиентски истории или реакции, които можеш да превърнеш във видео','5 мин','да превръщаш клиентско доказателство в етична история','Имаш доволни клиенти, но общото „страхотна услуга“ не доказва конкретна промяна.','Силната история има преди, препятствие, действие и измерим след; съгласието за употреба е задължително.','Клиент описва забавен процес, показва новия срок и разрешава конкретният резултат да бъде споделен.','Поискай разрешение и структурирай три истории без да добавяш непотвърдени твърдения.','Кое доказателство е най-силно?','Конкретна промяна с разрешение от клиента','Анонимна суперлатива без контекст','Резултат, който клиентът не е потвърдил','client_simulation'),
('s02-m01','pv01-20','Реши кои от следващите 5 идеи стават кратко видео и кои — дълго','5 мин','да избираш дължина според сложността и намерението','Натъпкваш процес с пет стъпки в 15 секунди или разтягаш една идея до осем минути.','Краткото видео носи една промяна или любопитство; дългото оправдава контекст, доказателства и последователни решения.','Един lighting hack е short; сравнение на три осветителни схеми с тестове е long.','Класифицирай пет свои идеи и запиши какво трябва да отпадне или да се добави.','Кога идеята заслужава дълъг формат?','Когато стойността изисква контекст и свързани стъпки','Когато заглавието е дълго','Винаги, когато има нова камера','decision_tree'),
('s02-m01','pv01-21','Напиши хук по формулата hook-loop-CTA за 3 различни теми','5 мин','да отваряш любопитство и да го затваряш с релевантно действие','Hook обещава резултат, но видеото не затваря обещанието или CTA идва без логика.','Hook спира, loop държи незавършен въпрос, а CTA е естествената следваща стъпка след отговора.','„Този кадър изглежда скъп заради една сянка“ отваря loop, демонстрацията го затваря, CTA кани към чеклист.','Напиши три пълни вериги и провери дали CTA следва директно от дадената стойност.','Кой CTA е логичен?','Действие, което продължава решението от видеото','Произволно „купи сега“','Нова тема без връзка с hook-а','step_reveal'),
('s02-m01','pv01-22','Направи карусел от 6 кадъра по един от готовите ти клипове','5 мин','да преработваш видео в самостоятелен визуален разказ','Шест screenshot-а от видеото не образуват карусел, ако липсва логика между тях.','Всеки кадър има една функция: обещание, контекст, стъпки, доказателство и следващо действие.','Демонстрация за звук става cover, проблем, три корекции и финален checklist.','Разпиши функциите на шестте кадъра и премахни всеки, който не движи историята.','Как каруселът остава разбираем без видеото?','Всеки кадър носи ясна част от самостоятелна последователност','Използва само красиви стоп-кадри','Скрива основната идея до описанието','sequence_sort'),
('s02-m01','pv01-23','Изгради календар за следващите 2 седмици с конкретни дати','5 мин','да планираш реалистично производство и публикуване','Седем публикации са записани за седмица, но няма ден за снимане или време за одобрение.','Календарът включва задача, собственик, зависимост и резерв — не само дата на публикация.','Три видеа се снимат на batch сесия, редакцията има срок, а петък остава за реакция по данните.','Постави конкретни дати за идея, сценарий, снимане, монтаж, преглед и публикация.','Какво липсва в календар само с дати за публикация?','Производствените стъпки и отговорникът','Още цветове в таблицата','Повече хаштагове','checklist'),
('s02-m01','pv01-24','Публикувай нещо тази седмица само за да тестваш реакция','5 мин','да формулираш малък тест и да учиш от реално поведение','Чакаш „перфектната“ публикация и губиш обратната връзка, която би подобрила следващата.','Добър тест променя една хипотеза, определя метрика предварително и не превръща слаб резултат в присъда за целия бранд.','Публикуват се два hooks към една тема в различни дни и се сравнява задържането в първите секунди.','Избери една хипотеза, публикувай минимален тест и запиши решение за следващата итерация.','Какво прави публикацията експеримент?','Предварително зададени хипотеза и метрика','Надеждата да стане viral','Промяна на пет елемента наведнъж','reflection'),

('s03-m01','lm01-01','AI тестът за препоръка — питай ChatGPT/Gemini „кой е най-добрият“ и виж дали си там','6 мин','да проверяваш как AI описва категорията и присъствието ти','Потенциален клиент пита AI за препоръка, а твоят бизнес липсва или е описан неточно.','Тестът се прави с неутрални въпроси в няколко системи, после твърденията се сверяват с реални публични източници.','Локална агенция се появява само при търсене по име, но не и при проблем, който решава.','Пусни три неутрални въпроса, запиши цитираните конкуренти и липсващите факти за теб.','Кой тест дава най-полезен сигнал?','Неутрален въпрос по клиентски проблем в няколко AI системи','Въпрос, който съдържа собственото ти име като отговор','Един въпрос в собствения ти чат с история','sequence_sort'),
('s03-m01','lm01-02','Категория на един — как да излезеш от сравнението „кой е по-евтин“ завинаги','6 мин','да формулираш категория, в която стойността ти е сравнима по резултат, не само по цена','Когато звучиш като всички, клиентът използва единственото лесно сравнение — цената.','Категорията на един комбинира конкретна аудитория, важен проблем, различен механизъм и доказуем резултат.','Вместо „маркетинг агенция“: система за записвания на семейни хотели чрез локално търсене и видео доказателства.','Напиши три версии и премахни всяка дума, която конкурент може да копира без промяна.','Кое позициониране намалява ценовото сравнение?','Конкретна аудитория, проблем, механизъм и доказателство','„Високо качество на добри цени“','Дълъг списък с всички услуги','matching'),
('s03-m01','lm01-03','Founder brand като маркетингов актив','7 мин','да превръщаш експертизата на основателя в доверие без култ към личността','Фирмената страница публикува безлични обещания, докато клиентът иска да разбере кой носи отговорност.','Founder brand работи, когато показва ясна гледна точка, решения и доказателства, които подсилват компанията и могат да се предадат на екипа.','Основател обяснява защо отказва неподходящ проект и показва стандарта, който екипът следва.','Избери три теми, по които основателят има доказуема позиция, и свържи всяка с фирмен процес.','Кога founder brand е устойчив актив?','Когато личната експертиза изгражда преносимо доверие към компанията','Когато всичко зависи от ежедневното присъствие на едно лице','Когато споделя само лични моменти без връзка с клиента','client_simulation'),
('s03-m01','lm01-04','Позициониране срещу реклама — грешката, която пали пари на вятъра','6 мин','да различаваш проблем в посланието от проблем в разпространението','Увеличаваш бюджета към страница, на която непознат не разбира за кого е офертата.','Рекламата усилва вече ясното позициониране; тя не поправя неразличима оферта, липсващо доказателство или грешна аудитория.','Преди нов бюджет екипът тества дали пет целеви клиента могат да повторят офертата със свои думи.','Направи петсекунден тест на страницата и определи дали първо се поправя послание или канал.','Кога има смисъл да увеличиш рекламния бюджет?','Когато правилната аудитория разбира и приема ясно доказана оферта','Когато посланието още се променя всеки ден','Когато няма измерено действие след клика','decision_tree'),
('s03-m01','lm01-05','Слабото място на всеки от 5-те ти конкурента','7 мин','да откриваш незаета клиентска нужда чрез публични доказателства','Конкурентният анализ се превръща в копиране на дизайн и цени вместо търсене на неудовлетворена нужда.','Търси повтарящи се оплаквания, неясни обещания, липсващи доказателства и сегменти, които конкурентът съзнателно не обслужва.','Отзивите хвалят резултата, но критикуват бавната комуникация — възможност за прозрачен процес със срокове.','Одитирай сайтове, отзиви и оферти на пет конкурента и запиши доказателство за всяка слабост.','Коя слабост е използваема за позициониране?','Повтарящ се клиентски проблем, който можеш надеждно да решиш','Цвят на лого, който лично не харесваш','Единичен анонимен коментар без контекст','checklist'),
('s03-m01','lm01-06','Тестът на огледалото — какво казват клиентите зад гърба ти','6 мин','да сравняваш желаното позициониране с реалните думи на клиентите','Брандът казва „стратегически партньор“, а клиентите го препоръчват само като „бърз изпълнител“.','Истинската позиция живее в повтарящите се думи след проекта; разликата с желаното обещание показва какво трябва да се докаже или промени.','Три интервюта повтарят „обясняват ясно“, което се превръща в доказуема част от офертата.','Попитай пет клиенти как биха те препоръчали с едно изречение и групирай точните им думи.','Кой отговор е най-ценен?','Повтаряща се конкретна фраза от реални клиенти','Комплимент, подсказан във въпроса','Собственият ти slogan','reflection'),
('s03-m01','lm01-07','От позициониране към бюджет — как основата определя следващите левове','7 мин','да разпределяш маркетинг бюджет според доказана пречка във фунията','Парите се делят по навик между канали, без връзка с това дали липсва внимание, доверие или конверсия.','Бюджетът следва ограничението: първо измери къде губиш подходящия клиент, после финансирай най-малкия тест, който може да промени решението.','При силен трафик и слаб booking първият бюджет отива в оферта и доказателство, не в още impressions.','Начертай пътя до покупка, посочи най-голямата загуба и предложи един ограничен тест с критерий за спиране.','Къде трябва да отиде следващият бюджет?','В най-добре доказаното ограничение с измерим тест','По равно във всеки наличен канал','В канала с най-много последователи','calculator');

DO $$
DECLARE
 spec record; lesson_uuid uuid; version_uuid uuid; next_version integer; interaction_content jsonb;
 interaction_key jsonb; block_uuid uuid; validation_result jsonb;
BEGIN
 FOR spec IN SELECT * FROM reference_lesson_specs ORDER BY module_id,lesson_id LOOP
  INSERT INTO public.academy_lessons(module_id,lesson_id,status,created_at,updated_at)
  VALUES(spec.module_id,spec.lesson_id,'published',now(),now())
  ON CONFLICT(module_id,lesson_id) DO UPDATE SET updated_at=now()
  RETURNING id INTO lesson_uuid;

  SELECT coalesce(max(version_number),0)+1 INTO next_version FROM public.academy_lesson_versions WHERE academy_lesson_id=lesson_uuid;
  INSERT INTO public.academy_lesson_versions(
   academy_lesson_id,version_number,title,subtitle,duration,objective,hook,estimated_minutes,
   source_kind,change_note
  ) VALUES(
   lesson_uuid,next_version,spec.title,'Практически урок с проверимо действие',spec.duration,
   'След този урок ще можеш '||spec.objective||'.',spec.hook,
   greatest(5,coalesce((regexp_match(spec.duration,'[0-9]+'))[1]::integer,10)),
   'reference','Lesson Engine V2 reference curriculum'
  ) RETURNING id INTO version_uuid;

  interaction_key:='{}'::jsonb;
  interaction_content:=CASE spec.interaction
   WHEN 'sequence_sort' THEN jsonb_build_object('instruction','Подреди действията така, че резултатът да може да бъде проверен.','items',jsonb_build_array(
    jsonb_build_object('id','observe','text',spec.example_text),jsonb_build_object('id','frame','text',spec.insight),jsonb_build_object('id','act','text',spec.practice)))
   WHEN 'matching' THEN jsonb_build_object('instruction','Свържи проблема, принципа и действието.','left',jsonb_build_array(
    jsonb_build_object('id','problem','text','Проблемът'),jsonb_build_object('id','principle','text','Работещият принцип'),jsonb_build_object('id','action','text','Следващото действие')),
    'right',jsonb_build_array(jsonb_build_object('id','a','text',spec.hook),jsonb_build_object('id','b','text',spec.insight),jsonb_build_object('id','c','text',spec.practice)))
   WHEN 'step_reveal' THEN jsonb_build_object('steps',jsonb_build_array(
    jsonb_build_object('id','notice','title','Забележи','text',spec.hook),jsonb_build_object('id','understand','title','Разбери','text',spec.insight),jsonb_build_object('id','apply','title','Приложи','text',spec.practice)))
   WHEN 'flip_cards' THEN jsonb_build_object('cards',jsonb_build_array(
    jsonb_build_object('id','principle','front','Принцип','back',spec.insight),jsonb_build_object('id','example','front','Пример','back',spec.example_text),jsonb_build_object('id','action','front','Действие','back',spec.practice)))
   WHEN 'checklist' THEN jsonb_build_object('items',jsonb_build_array(
    jsonb_build_object('id','understand','text',spec.insight,'required',true),jsonb_build_object('id','inspect','text',spec.example_text,'required',true),jsonb_build_object('id','do','text',spec.practice,'required',true)))
   WHEN 'prompt_builder' THEN jsonb_build_object('minFields',3,'fields',jsonb_build_array(
    jsonb_build_object('id','context','label','Контекст','placeholder',spec.hook),jsonb_build_object('id','principle','label','Принцип','placeholder',spec.insight),jsonb_build_object('id','output','label','Желан резултат','placeholder',spec.practice)))
   WHEN 'reflection' THEN jsonb_build_object('prompt',spec.practice||' Обясни и коя своя хипотеза ще провериш.','minLength',60)
   WHEN 'homework' THEN jsonb_build_object('prompt',spec.practice,'minLength',80)
   WHEN 'before_after' THEN jsonb_build_object('before',jsonb_build_object('label','Слаб избор','text',spec.wrong_answer_1),'after',jsonb_build_object('label','Работещ избор','text',spec.correct_answer))
   WHEN 'calculator' THEN jsonb_build_object('prompt','Оцени от 1 до 5 колко ясно можеш да докажеш: '||spec.insight,'label','Оценка','unit','от 5','hint','Под 4 означава, че е нужно още доказателство')
   ELSE jsonb_build_object('prompt',spec.hook,'options',jsonb_build_array(
    jsonb_build_object('id','a','label',spec.correct_answer),jsonb_build_object('id','b','label',spec.wrong_answer_1),jsonb_build_object('id','c','label',spec.wrong_answer_2)))
  END;

  interaction_key:=CASE spec.interaction
   WHEN 'sequence_sort' THEN '{"order":["frame","observe","act"]}'::jsonb
   WHEN 'matching' THEN '{"matches":{"problem":"a","principle":"b","action":"c"}}'::jsonb
   WHEN 'calculator' THEN '{"min":4,"max":5}'::jsonb
   WHEN 'decision_tree' THEN '{"correct":"a"}'::jsonb
   WHEN 'scenario' THEN '{"correct":"a"}'::jsonb
   WHEN 'client_simulation' THEN '{"correct":"a"}'::jsonb
   ELSE '{}'::jsonb END;

  INSERT INTO public.academy_lesson_blocks(version_id,block_key,position,block_type,title,content,required,points) VALUES
   (version_uuid,'objective',0,'objective','Цел на урока',jsonb_build_object('body','След този урок ще можеш '||spec.objective||'.'),true,5),
   (version_uuid,'hook',1,'hook','Реалният проблем',jsonb_build_object('body',spec.hook),true,5),
   (version_uuid,'concept',2,'concept','Принципът зад решението',jsonb_build_object('body',spec.insight),true,5),
   (version_uuid,'interaction',3,spec.interaction,'Приложи принципа',interaction_content,true,10),
   (version_uuid,'example',4,'example','Практически пример',jsonb_build_object('body',spec.example_text),true,5),
   (version_uuid,'case',5,'case_study','Казус и решение',jsonb_build_object('case',spec.hook,'solution',spec.insight),true,5),
   (version_uuid,'quiz',6,'quiz','Проверка на разбирането',jsonb_build_object('question',spec.quiz_question,'options',jsonb_build_array(
    jsonb_build_object('id','a','label',spec.correct_answer),jsonb_build_object('id','b','label',spec.wrong_answer_1),jsonb_build_object('id','c','label',spec.wrong_answer_2))),true,15),
   (version_uuid,'practice',7,'practical_response','Практическа задача',jsonb_build_object('prompt',spec.practice,'minLength',60,'placeholder','Опиши конкретно какво ще направиш и как ще провериш резултата.'),true,15),
   (version_uuid,'reflection',8,'reflection','Какво променяш оттук нататък?',jsonb_build_object('prompt','Коя част от досегашния ти подход се променя след този урок и защо?','minLength',40),true,5),
   (version_uuid,'summary',9,'summary','Обобщение и следваща стъпка',jsonb_build_object('takeaways',jsonb_build_array(spec.insight,spec.example_text),'nextStep',spec.practice),true,5);

  SELECT id INTO block_uuid FROM public.academy_lesson_blocks WHERE version_id=version_uuid AND block_key='quiz';
  INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring)
  VALUES(block_uuid,'{"correct":"a"}',jsonb_build_object('explanation',spec.insight,'incorrect','Върни се към принципа и сравни избора с конкретния пример.'),'{"mode":"single_choice"}');

  IF interaction_key<>'{}'::jsonb THEN
   SELECT id INTO block_uuid FROM public.academy_lesson_blocks WHERE version_id=version_uuid AND block_key='interaction';
   INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring)
   VALUES(block_uuid,interaction_key,jsonb_build_object('explanation',spec.insight),jsonb_build_object('mode',spec.interaction));
  END IF;

  validation_result:=academy_private.lesson_validation(version_uuid);
  IF jsonb_array_length(validation_result->'errors')>0 THEN
   RAISE EXCEPTION 'Invalid reference lesson %/%: %',spec.module_id,spec.lesson_id,validation_result;
  END IF;
  UPDATE public.academy_lesson_versions SET validation=validation_result WHERE id=version_uuid;
  UPDATE public.academy_lessons SET status='published',published_version_id=version_uuid,draft_version_id=version_uuid,updated_at=now() WHERE id=lesson_uuid;
  INSERT INTO public.academy_lesson_audit(academy_lesson_id,version_id,action,details)
  VALUES(lesson_uuid,version_uuid,'published',jsonb_build_object('source','reference_module','version',next_version));
 END LOOP;
END $$;

-- Move progress to the new reference versions. Completed lessons remain completed;
-- unfinished lessons restart safely because block identities and completion rules changed.
UPDATE public.academy_lesson_progress progress
SET version_id=lesson.published_version_id,
 current_block_key=(SELECT block_key FROM public.academy_lesson_blocks WHERE version_id=lesson.published_version_id ORDER BY position LIMIT 1),
 block_state='{}',
 completed_block_keys=CASE WHEN progress.completed_at IS NOT NULL THEN (SELECT array_agg(block_key ORDER BY position) FROM public.academy_lesson_blocks WHERE version_id=lesson.published_version_id) ELSE '{}'::text[] END,
 xp=CASE WHEN progress.completed_at IS NOT NULL THEN (SELECT coalesce(sum(points),0)::integer FROM public.academy_lesson_blocks WHERE version_id=lesson.published_version_id) ELSE 0 END,
 score_percent=CASE WHEN progress.completed_at IS NOT NULL THEN progress.score_percent ELSE NULL END,
 mastery_status=CASE WHEN progress.completed_at IS NOT NULL THEN progress.mastery_status ELSE 'learning' END,
 last_activity_at=now()
FROM public.academy_lessons lesson
WHERE progress.academy_lesson_id=lesson.id AND lesson.module_id IN ('s01-m01','s02-m01','s03-m01')
 AND progress.version_id IS DISTINCT FROM lesson.published_version_id;
